BEGIN TRANSACTION;
CREATE TABLE products (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        barcode TEXT UNIQUE NOT NULL,
        brand TEXT,
        name TEXT NOT NULL,
        name_ar TEXT,
        name_fr TEXT,
        category TEXT,
        category_fr TEXT,
        unit TEXT,
        indicative_price REAL DEFAULT 0.0,
        vat_rate REAL DEFAULT 19.0,
        image_url TEXT,
        is_algerian_origin BOOLEAN DEFAULT 0
    );



